<script setup>
import { computed, ref } from 'vue'
import { ArrowUpRight, Plus } from 'lucide-vue-next'
import { effectiveDishes, groupMonths, recordPhoto } from '../cookingJournal.js'
import CookingRecordDetail from './CookingRecordDetail.vue'
import '../kitchen-journal.css'
const props=defineProps({journal:{type:Object,required:true}})
const emit=defineEmits(['browse','cook','manual'])
const mode=ref('wall'),month=ref(''),detail=ref(null),manual=ref(''),showManual=ref(false),localError=ref('')
const months=computed(()=>groupMonths(props.journal.records))
const safely=async fn=>{localError.value='';try{return await fn()}catch(e){localError.value=e.message}}
async function open(id){const record=await safely(()=>props.journal.getRecord(id));if(record)detail.value=record}
async function add(){await safely(async()=>{const r=await props.journal.start({manual_name:manual.value.trim()});if(r){emit('manual',r);emit('cook')}})}
async function again(dish){await safely(async()=>{const r=await props.journal.start({manual_name:'继续练习',dish_key:dish.dish_key});if(r)emit('cook')})}
function load(page=1){safely(()=>props.journal.loadRecords({page,state:'completed',month:month.value,dish_key:''}))}
</script>
<template><section class="kj kj-footprints"><header class="kj-heading"><div><span class="kj-eyebrow">A PERSONAL ARCHIVE OF EVERYDAY MEALS</span><h1>我的厨房足迹</h1><p>从第一次开火，到慢慢有了自己的拿手菜。</p></div><button @click="showManual=!showManual"><Plus :size="17" /> 补记一餐</button></header><form v-if="showManual" class="kj-manual kj-paper" @submit.prevent="add"><label for="footprint-manual">补记一道做过的菜</label><div class="kj-actions"><input id="footprint-manual" v-model="manual" required maxlength="80" placeholder="写下真实做过的菜名" /><button class="kj-primary" :disabled="!manual.trim()">去记下这一餐</button></div><small>日期、结果和照片，在收尾时填写。</small></form><p v-if="localError||journal.error" class="kj-error" role="alert">{{ localError||journal.error }}</p><template v-if="journal.summary.meals"><div class="kj-archive-intro"><p>你已留下 <strong>{{ journal.summary.meals }}</strong> 餐 · 尝试 <strong>{{ journal.summary.dishes }}</strong> 道菜</p><div><span class="kj-level">{{ journal.summary.level.title }}</span><small>{{ journal.summary.level.remaining ? `再留 ${journal.summary.level.remaining} 餐，迎接下一段成长。` : '把熟悉的味道，慢慢做成自己的拿手菜。' }}</small></div></div><section class="kj-achievements" aria-label="我的厨房印章"><button v-for="stamp in journal.summary.achievements" :key="stamp.id" :class="['kj-achievement',{'is-unlocked':stamp.unlocked}]" :disabled="!stamp.unlocked" @click="open(stamp.session_id)"><span class="kj-achievement-seal">{{ stamp.title }}</span><strong>{{ stamp.unlocked?'已留印':'等待烟火' }}</strong><small>{{ stamp.description }}</small><time v-if="stamp.unlocked_at">{{ new Date(stamp.unlocked_at).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'}) }}</time></button></section><div class="kj-browser-head"><div class="kj-tabs"><button v-for="tab in [{id:'wall',name:'作品墙'},{id:'time',name:'时间足迹'},{id:'repertoire',name:'拿手菜'}]" :key="tab.id" :aria-pressed="mode===tab.id" @click="mode=tab.id">{{ tab.name }}</button></div><label v-if="mode!=='repertoire'" class="kj-month-filter">翻到某个月<input v-model="month" type="month" @change="load()" /><button v-if="month" @click="month='';load()">全部月份</button></label></div><template v-if="mode!=='repertoire'"><div v-if="!journal.records.length" class="kj-paper kj-empty"><p>这个月还没有留下记录。</p><button @click="month='';load()">看看所有足迹</button></div><section v-for="group in months" :key="group.month" class="kj-month-group"><h2 class="kj-month-title">{{ group.month.replace('-',' · ') }}<small>烟火存档</small></h2><div :class="mode==='wall'?'kj-wall':'kj-timeline'"><template v-for="record in group.items" :key="record.id"><button v-if="mode==='wall'" :class="['kj-work-card',{'kj-text-card':!recordPhoto(record)}]" @click="open(record.id)"><div class="kj-card-visual"><img v-if="recordPhoto(record)" :src="recordPhoto(record)" :alt="effectiveDishes(record).map(d=>d.snapshot.name).join('、')+'成品照片'" loading="lazy" /><span v-else>{{ effectiveDishes(record).map(d=>d.snapshot.name).join(' · ') }}</span><span class="kj-card-no">NO. {{ String(record.number).padStart(3,'0') }}</span></div><div class="kj-card-copy"><time>{{ record.cooked_on }}</time><h3>{{ record.title||effectiveDishes(record).map(d=>d.snapshot.name).join('、') }}</h3><p>{{ record.note||effectiveDishes(record).map(d=>d.note).filter(Boolean).join(' · ')||'这一餐，认真尝试过。' }}</p><span class="kj-card-open">展开这一餐 <ArrowUpRight :size="16" /></span></div></button><details v-else class="kj-paper kj-time-record"><summary><time>{{ record.cooked_on.slice(5) }}</time><strong>{{ record.title||effectiveDishes(record).map(d=>d.snapshot.name).join('、') }}</strong><span>No. {{ String(record.number).padStart(3,'0') }}</span></summary><div class="kj-time-body"><img v-if="recordPhoto(record)" :src="recordPhoto(record)" alt="这一餐的成品照片" /><p>{{ record.note||'这一天，留下一餐。' }}</p><button @click="open(record.id)">展开记录与心得 →</button></div></details></template></div></section><div class="kj-pagination"><button :disabled="journal.page<=1" @click="load(journal.page-1)">上一页</button><span>{{ journal.page }} / {{ Math.max(1,Math.ceil(journal.total/12)) }}</span><button :disabled="journal.page*12>=journal.total" @click="load(journal.page+1)">下一页</button></div></template><div v-else class="kj-repertoire"><article v-for="dish in journal.summary.repertoire" :key="dish.dish_key" class="kj-paper"><div class="kj-spread"><h2>{{ dish.name }}</h2><span class="kj-outcome-tag">{{ {tried:'试过',practice:'练习中',signature:'我的拿手菜'}[dish.status] }}</span></div><p>认真尝试 {{ dish.attempts }} 次 · 做成 {{ dish.successes }} 次</p><p class="kj-own-note">{{ dish.last_note||'下次的发现，留给下次。' }}</p><small>最近一次 · {{ dish.last_cooked_on }}</small><label>给这道菜做个标记<select :value="dish.status" @change="safely(()=>journal.markDish(dish.dish_key,$event.target.value))"><option value="tried">试过</option><option value="practice">练习中</option><option value="signature">我的拿手菜</option></select></label><small class="kj-muted">这是自己的标记，与自动获得的印章分开。</small><div class="kj-actions"><button @click="open(dish.sessions[0])">回看记录</button><button @click="again(dish)">再做一次 →</button></div></article></div></template><div v-else-if="!journal.loading" class="kj-empty kj-paper"><span class="kj-empty-mark">迹</span><h2>第一餐，从这里开始。</h2><p>不必等到厨艺精湛。亲手做过的一道菜，<br>一张照片，或一句留给下次的话，都值得留下。</p><button class="kj-primary" @click="emit('browse')">开始做一道菜</button><button @click="showManual=true">补记做过的菜</button></div><p v-else class="kj-muted" role="status">正在翻开厨房足迹…</p><CookingRecordDetail :journal="journal" :record="detail" @close="detail=null" @cook="emit('cook')" /></section></template>
